#include "Studio.h"
namespace pulse {
using namespace juce;
void Studio::runStereoChecks(const File& folder,const std::function<void(bool,const String&)>& check){
    cancelNoteTool();closeCommandPalette();perform(analyzerBack);project=emptyProject();project.bpm=120;project.loop=false;currentFile=File();selectedTrack=7;selectedNotes.clear();selectedNote=-1;project.patterns[0].length=4;lane()={{0,1,60,.8f}};undoStack.clear();redoStack.clear();publish();perform(stop);setSize(1180,800);resetLayout();showPane(mixerPane);
    auto draw=[&]{hits.clear();Image image(Image::RGB,getWidth(),getHeight(),true);Graphics g(image);paint(g);};auto event=[&](Point<float> p,int mods=ModifierKeys::leftButtonModifier){auto t=Time::getCurrentTime();return MouseEvent(Desktop::getInstance().getMainMouseSource(),p,ModifierKeys(mods),1,0,0,0,0,this,this,t,p,t,1,false);};
    draw();auto find=[&](int action){return std::find_if(hits.begin(),hits.end(),[&](const Hit& h){return h.action==action;});};auto button=find(stereoOpen);check(button!=hits.end(),"Mixer exposes Stereo tools beside Analyzer");if(button!=hits.end()){auto click=event(button->rect.getCentre());mouseDown(click);mouseUp(click);}check(selectedEffect==6&&activePane==effectsPane&&paneCount==15,"stereo tools reuse the existing effects window");auto original=JSON::toString(projectToJson(project));perform(stereoEnable);check(project.tracks[7].mixer.stereo.enabled&&undoStack.size()==1,"stereo enable is one project edit");perform(undoAction);check(JSON::toString(projectToJson(project))==original,"stereo enable Undo restores all original data");perform(redoAction);
    panes[effectsPane].bounds=boundedPane({260,150,620,390},effectsPane);draw();std::map<int,Rectangle<float>> controlMap;bool fits=true;for(const auto& h:hits)if(h.pane==effectsPane&&h.action>=stereoEnable&&h.action<=stereoTrim){if(controlMap.count(h.action))controlMap[h.action]=controlMap[h.action].getUnion(h.rect);else controlMap[h.action]=h.rect;fits&=panes[effectsPane].bounds.contains(h.rect);}std::vector<Rectangle<float>> controls;for(const auto& entry:controlMap)controls.push_back(entry.second);bool overlaps=false;for(size_t i=0;i<controls.size();++i)for(size_t j=i+1;j<controls.size();++j)overlaps|=controls[i].intersects(controls[j]);check(fits&&!overlaps&&controls.size()==8,"stereo controls fit the minimum effects window without overlap");snapshot(folder.getChildFile("stereo-tools.png"));
    auto prior=project.tracks[7].mixer.stereo;undoStack.clear();auto knob=find(stereoWidth);if(knob!=hits.end()){auto point=knob->rect.getCentre();mouseDown(event(point));mouseDrag(event(point+Point<float>(0,-35)));mouseUp(event(point));}check(project.tracks[7].mixer.stereo.width>prior.width&&undoStack.size()==1,"stereo width drag groups into one undo");perform(undoAction);check(project.tracks[7].mixer.stereo==prior,"width drag Undo restores exact stereo settings");draw();knob=find(stereoTrim);MouseWheelDetails wheel;wheel.deltaY=-.1f;if(knob!=hits.end())mouseWheelMove(event(knob->rect.getCentre()),wheel);check(project.tracks[7].mixer.stereo.trim<0,"stereo trim wheel uses the project parameter path");perform(undoAction);setParameter(stereoWidth,7,1);draw();knob=find(stereoWidth);if(knob!=hits.end()){auto click=event(knob->rect.getCentre(),ModifierKeys::leftButtonModifier|ModifierKeys::altModifier);mouseDown(click);mouseUp(click);}check(project.tracks[7].mixer.stereo.width==1,"Alt-click resets width to 100 percent");perform(undoAction);check(project.tracks[7].mixer.stereo.width==2,"stereo parameter Reset supports undo");
    for(int action:{stereoMono,stereoSwap,stereoInvertLeft,stereoInvertRight}){auto before=project.tracks[7].mixer.stereo;auto count=undoStack.size();perform(action);check(project.tracks[7].mixer.stereo!=before&&undoStack.size()==count+1,"stereo switches create one undoable change");perform(undoAction);check(project.tracks[7].mixer.stereo==before,"switch Undo restores stereo settings exactly");}
    auto stereo=project.tracks[7].mixer.stereo;perform(stereoReset);check(project.tracks[7].mixer.stereo==StereoSettings{},"Reset bypasses and clears all stereo settings");auto count=undoStack.size();perform(stereoReset);check(undoStack.size()==count,"already-default stereo Reset adds no history");perform(undoAction);check(project.tracks[7].mixer.stereo==stereo,"Stereo Reset Undo restores all stored flags and levels");
    auto before=project.tracks[7].mixer.stereo;check(applyEffectChain(factoryEffectChains()[3],7)&&project.tracks[7].mixer.stereo==before,"six-effect chain recall preserves the separate post-chain stereo utility");perform(undoAction);project.tracks[5].isBus=true;selectedTrack=5;perform(stereoEnable);perform(stereoMono);check(project.tracks[5].mixer.stereo.enabled&&project.tracks[5].mixer.stereo.mono&&project.tracks[7].mixer.stereo==before,"bus stereo editing is independent of source inserts");selectedTrack=7;
    auto frozen=JSON::toString(projectToJson(project));count=undoStack.size();recording=true;perform(stereoEnable);perform(stereoReset);setParameter(stereoWidth,7,.1f);editStereoValue(0);check(JSON::toString(projectToJson(project))==frozen&&undoStack.size()==count&&Component::getCurrentlyModalComponent()==nullptr,"recording locks stereo switches, reset, knobs and typed dialogs");recording=false;setParameter(stereoTrim,7,std::numeric_limits<float>::quiet_NaN());check(JSON::toString(projectToJson(project))==frozen,"nonfinite editor stereo values are ignored");
    Project loaded;auto file=folder.getChildFile("stereo-editor.pulse");check(saveProject(project,file).wasOk()&&loadProject(file,loaded).wasOk()&&loaded.tracks[7].mixer.stereo==before&&loaded.tracks[5].mixer.stereo==project.tracks[5].mixer.stereo&&loaded.patterns[0].length==4,"editor stereo state and variable steps survive project save/reopen");
    auto entries=paletteEntries();check(!searchCommands(entries,"stereo tools").empty()&&!searchCommands(entries,"channel mono").empty(),"Ctrl+P exposes stereo tools and mono commands");perform(analyzerChannel);check(analyzerView&&selectedEffect==6,"stereo tools open the selected-channel analyzer without losing editor selection");perform(analyzerBack);check(!analyzerView&&selectedEffect==6,"analyzer Effects returns to Stereo tools");perform(effectsTab,2);check(selectedEffect==2,"Stereo tools return to the six effect editors normally");
    project.tracks[7].mixer.stereo={};selectedTrack=7;perform(stereoEnable);perform(stereoInvertRight);publish();perform(analyzerChannel);perform(play);AudioBuffer<float> audio(2,512);for(int i=0;i<100;++i){getNextAudioBlock(AudioSourceChannelInfo(&audio,0,512));updateAnalyzer();if(i==20)perform(analyzerReset);}check(analyzerModel.correlationReady()&&analyzerModel.correlation()<-.999&&analyzerModel.peakHold(0)>.001,"actual channel analyzer observes polarity-inverted callback audio after stereo tools");perform(stop);perform(analyzerBack);perform(stereoOpen);
}
}
